def _sets_a_block_kind(node: ast.AST) -> bool:
    """Whether this function leaves a ticket carrying a kind (never clears one)."""
    for sub in ast.walk(node):
        if not isinstance(sub, ast.Assign):
            continue
        for target in sub.targets:
            if not (isinstance(target, ast.Attribute) and target.attr == "block_kind"):
                continue
            if isinstance(sub.value, ast.Constant) and sub.value.value is None:
                continue
            return True
    return False

